from pathlib import Path
import json,html
R=Path(__file__).resolve().parent.parent;S=R/'source';I=json.loads((S/'icons.json').read_text())
def ic(n):return I[n]
def a(scene,label,cls=''):return f'<a class="{cls}" href="{scene}.html">{label}</a>'
def btn(t,scene=None,secondary=False):return a(scene,t,'button secondary' if secondary else 'button') if scene else f'<button type="button" class="button {"secondary" if secondary else ""}">{t}</button>'
def im(n,alt,cls=''):return f'<img class="{cls}" src="../assets/{n}.png" alt="{alt}">'
def eyebrow(t):return f'<div class="eyebrow">{t}</div>'
def field(label,value='',full=False,type='text',help='',error=''):
 id=label.lower().replace(' ','-')
 return f'<div class="field {"full" if full else ""}"><label for="{id}">{label}</label><input id="{id}" type="{type}" value="{html.escape(value,quote=True)}" {"aria-invalid=true aria-describedby="+id+"-error" if error else ""}>{f"<small>{help}</small>" if help else ""}{f"<span class=error id={id}-error>{error}</span>" if error else ""}</div>'
P=[dict(id='cloud-rinse',name='Cloud Rinse',kind='Gel cleanser',qty='150 ml',price=640,stage='Cleanse',asset='cleanser',note='Face · Rinse-off'),dict(id='daily-veil',name='Daily Veil',kind='Face cream',qty='50 g',price=880,stage='Care',asset='cream',note='Face · Leave-on'),dict(id='soft-colour',name='Soft Colour',kind='Lip tint',qty='6 ml',price=520,stage='Colour',asset='tint',note='Lips · 3 named shades'),dict(id='palm-wash',name='Palm Wash',kind='Hand wash',qty='250 ml',price=460,stage='Cleanse',asset=None,note='Hands · Ingredients not supplied')]
def price(n):return '₹'+format(n,',')
def photo(p):return im(p['asset'],p['name']+' · '+p['kind']) if p['asset'] else '<div class="missing-photo">'+ic('Droplets')+'<span>Product image<br>not supplied</span></div>'
def header():return f'''<div class="announcement">A considered routine. Your own pace.</div><header class="header"><div class="wrap nav-row"><button class="icon-button mobile-menu" aria-label="Open menu" aria-expanded="false">{ic('Menu')}</button>{a('01-home-top','dewdrop','wordmark')}<nav class="desktop-nav" aria-label="Primary">{a('03-collection','Shop by use')}{a('02-home-bottom','The routine')}{a('05-product-facts','Ingredients')}{a('04-product-selection','Shades')}</nav><div class="utilities">{a('03-collection',ic('Search'), 'icon-button')}{a('12-profile',ic('UserRound'),'icon-button account-icon')}{a('07-cart',ic('ShoppingBag')+'<span class="bag-count">2</span>','icon-button bag')}</div></div><nav class="mobile-drawer" aria-label="Mobile menu" hidden>{a('03-collection','Shop by use')}{a('02-home-bottom','The routine')}{a('05-product-facts','Ingredients')}{a('04-product-selection','Named shades')}{a('12-profile','Your account')}</nav></header>'''
def footer():return f'''<footer><div class="wrap footer-grid"><div><span class="wordmark">dewdrop</span><p>Small moments.<br>A routine that is yours.</p></div><div><h3>Explore</h3>{a('03-collection','Shop by use')}{a('02-home-bottom','The routine')}{a('05-product-facts','Ingredients & directions')}</div><div><h3>Here to help</h3>{a('06-product-continuation','Shipping & returns')}{a('14-order-detail','Order support')}{a('13-orders','Your orders')}</div><div><h3>Your space</h3>{a('10-sign-in','Sign in with LetBuyy')}{a('12-profile','Profile')}{a('15-addresses','Addresses')}</div></div><div class="wrap footer-line"><span>© 2026 Dewdrop · Fictional design store</span><span>India / INR ₹ · Privacy · Terms</span></div></footer>'''
def crumbs(t):return f'<div class="crumbs">{a("01-home-top","Home")} {ic("ChevronRight")} {t}</div>'
def card(p):
 return f'''<article class="product-card"><a href="04-product-selection.html?product={p['id']}" class="product-photo">{photo(p)}</a><div class="card-facts"><span class="eyebrow">{p['stage']} / {p['kind']}</span><div class="card-title"><h3>{a('04-product-selection?product='+p['id'],p['name']) if False else f'<a href="04-product-selection.html?product={p["id"]}">{p["name"]}</a>'}</h3><strong>{price(p['price'])}</strong></div><p>{p['qty']} · {p['note']}</p><a class="text-link" href="04-product-selection.html?product={p['id']}">View product {ic('ArrowRight')}</a></div></article>'''
def routine(compact=False):
 out=''
 for i,p in enumerate(P[:3]):out+=f'<div class="routine-step"><span class="step-index">0{i+1}</span><div><h3>{p["stage"]}</h3><p>{["Start with a rinse-off product.","Choose a leave-on texture.","Finish with a named shade."][i]}</p></div>{a("03-collection",ic("ArrowRight"),"icon-button")}</div>'
 return '<div class="routine-strip">'+out+'</div>'
def context():return f'<div class="product-context"><div>{eyebrow("YOUR SELECTED PRODUCT")}<strong>Soft Colour lip tint · Rosewater · 6 ml</strong></div><span>{price(520)}</span>{a("04-product-selection","Back to selection "+ic("ArrowRight"),"text-link")}</div>'
def summary(cart=False):
 return f'''<aside class="summary panel"><h2>{'Bag summary' if cart else 'Your order'}</h2><div class="summary-item">{im('tint','Soft Colour lip tint')}<div><strong>Soft Colour</strong><p>Rosewater · 6 ml · Qty 1</p></div><b>₹520</b></div><div class="summary-item">{im('cleanser','Cloud Rinse cleanser')}<div><strong>Cloud Rinse</strong><p>150 ml · Qty 1</p></div><b>₹640</b></div><dl class="totals"><div><dt>Subtotal · 2 items</dt><dd>₹1,160</dd></div><div><dt>Shipping</dt><dd>{'Calculated at checkout' if cart else '₹60'}</dd></div><div><dt>Tax</dt><dd>Included in prices</dd></div><div class="total"><dt>{'Subtotal' if cart else 'Total'}</dt><dd><small>INR</small> {'₹1,160' if cart else '₹1,220'}</dd></div></dl>{'<p>Shipping is confirmed before you pay.</p>'+btn('Continue to checkout '+ic('ArrowRight'),'08-checkout-address') if cart else '<p class="small">Fictional server quote · No payment is taken.</p>'}</aside>'''
def checkout_header():return f'<header class="checkout-header"><div class="wrap nav-row">{a("07-cart","dewdrop","wordmark")}<span class="small inline">{ic("LockKeyhole")} Checkout by LetBuyy</span></div></header>'
def steps(review=False):return '<div class="checkout-steps"><span class="'+('' if review else 'current')+'">① Address</span>'+ic('ChevronRight')+'<span class="'+('current' if review else '')+'">② Review & pay</span></div>'
def account_nav(active):
 return '<aside class="account-nav"><div class="person"><span class="avatar">A</span><div><strong>Asha Rao</strong><p>asha@example.test</p></div></div><nav aria-label="Account">'+''.join(a(s,ic(i)+t,'active' if t==active else '') for s,t,i in [('12-profile','Overview','UserRound'),('13-orders','Orders','Package'),('15-addresses','Addresses','MapPin')])+a('10-sign-in',ic('LogOut')+'Sign out')+'</nav></aside>'
def account(title,sub,body,active='Overview'):
 return header()+f'<main class="wrap account-page">{eyebrow("YOUR DEWDROP ACCOUNT")}<h1>{title}</h1><p class="intro">{sub}</p><div class="account-layout">{account_nav(active)}<div class="account-main">{body}</div></div></main>'+footer()
def home_top():return header()+f'''<main><section class="hero"><div class="hero-copy">{eyebrow('CARE, ON YOUR TERMS')}<h1>A little care.<br>A daily ritual.</h1><p>Find your next everyday essential by what you use it for. Ingredients, directions and shades, clearly laid out.</p>{btn('Explore your routine '+ic('ArrowRight'),'03-collection')}<span class="hero-caption">Cleanse. Care. A touch of colour.</span></div><div class="hero-photo">{im('hero','Sage cleanser bottle, cream jar and rose lip tint on pale stone')}<span class="photo-caption">The everyday edit / 01</span></div></section><section class="wrap section slim"><div class="section-heading"><div>{eyebrow('CHOOSE YOUR NEXT STEP')}<h2>Start where you are.</h2></div><p>No prescribed set.<br>Each product is yours to choose.</p></div>{routine()}</section></main>'''
def home_bottom():return header()+f'''<main><section class="wrap section"><div class="section-heading"><div>{eyebrow('THE EVERYDAY SHELF')}<h1>Three steps. Your choices.</h1></div>{a('03-collection','Browse all products '+ic('ArrowRight'),'text-link')}</div><div class="cards three">{''.join(card(p) for p in P[:3])}</div></section><section class="education"><div class="education-photo">{im('cream','A cream jar and a cream texture on pale stone')}</div><div class="education-copy">{eyebrow('READ THE SMALL DETAILS')}<h2>Know what goes<br>into your routine.</h2><p>See the full ingredient list and directions for each product. Missing information is always marked.</p>{a('05-product-facts','Read ingredients & directions '+ic('ArrowRight'),'text-link')}<div class="quiet-note">No ingredient list supplied? Ask the merchant before choosing.</div></div></section><section class="wrap service-grid"><div>{ic('Droplets')}<h3>Use, clearly explained</h3><p>Product-specific directions, when supplied.</p></div><div>{ic('Package')}<h3>Before you order</h3><p>Read shipping and returns information.</p></div><div>{ic('CircleHelp')}<h3>Your order, in one place</h3><p>Sign in to view your Dewdrop orders.</p></div></section></main>'''+footer()
def collection():
 shelves=''
 for i,stage in enumerate(['Cleanse','Care','Colour']):
  shelves+=f'<section class="shelf" data-stage="{stage}"><div class="shelf-label"><span class="step-index">0{i+1}</span><div><h2>{stage}</h2><p>{["Rinse-off essentials","Leave-on textures","Named shades"][i]}</p></div></div><div class="shelf-products">'+''.join(card(p) for p in P if p['stage']==stage)+'</div></section>'
 return header()+f'''<main class="wrap section">{crumbs('Shop by use')}<div class="collection-intro">{eyebrow('THE ROUTINE SHELF')}<h1>Find your everyday.</h1><p>Browse by step. Buy each product independently.</p></div><form class="search-row" onsubmit="return false"><label class="search-field">{ic('Search')}<input type="search" placeholder="Search by product or use" aria-label="Search by product or use"></label><button class="button">Search</button></form><div class="filter-bar"><details><summary>{ic('Plus')} Routine stage</summary><div class="facet-options">{''.join(f'<label><input type="checkbox" name="stage" value="{s}">{s}</label>' for s in ['Cleanse','Care','Colour'])}</div></details><details><summary>{ic('Plus')} Format</summary><div class="facet-options">Gel · Cream · Tint</div></details><details><summary>{ic('Plus')} Named shades</summary><div class="facet-options">Rosewater · Pink Clay · Terracotta</div></details><label class="sort">Sort <select aria-label="Sort products"><option>Routine order</option><option>Price: low to high</option></select></label></div><div class="result-meta"><span id="result-count">4 products</span><button class="text-button" id="clear-filters">Clear filters</button></div>{shelves}<div class="pagination"><span>Showing all 4 products</span><nav aria-label="Pagination"><button disabled>Previous</button><span aria-current="page">1</span><button disabled>Next</button></nav></div></main>'''+footer()
def selection():return header()+f'''<main class="wrap section">{crumbs('Colour / Soft Colour')}<div class="pdp"><div class="gallery"><div class="main-product-image">{im('tint','Soft Colour lip tint and a dusty rose texture sample')}</div><div class="gallery-caption"><span>Bottle & texture / 01</span><span>Shade shown: Rosewater</span></div><div class="thumbs"><button aria-label="View Rosewater bottle" aria-pressed="true">{im('tint','Rosewater bottle')}</button><button aria-label="View routine still life">{im('hero','Routine still life')}</button></div></div><div class="purchase">{eyebrow('03 / COLOUR · LIPS')}<h1>Soft Colour<br>lip tint</h1><div class="price-line"><strong>₹520</strong><span>6 ml · Tax included</span></div><p>A wash of colour for your everyday. Choose by name, then read the details.</p><fieldset class="shade-picker"><legend>Shade — <strong id="shade-name">Rosewater</strong></legend><div class="shade-options"><label><input type="radio" name="shade" value="tint-rosewater" checked><span><i style="--shade:#a36a65"></i><b>Rosewater</b><small>Muted rose · RW01</small></span></label><label><input type="radio" name="shade" value="tint-pink-clay"><span><i style="--shade:#a36a65"></i><b>Pink Clay</b><small>Muted rose · PC02</small></span></label><label class="unavailable"><input type="radio" name="shade" value="tint-terracotta"><span><i style="--shade:#9a5944"></i><b>Terracotta</b><small>Unavailable · TC03</small></span></label></div></fieldset><p class="small" id="shade-identity">Selected: Rosewater · RW01. Screen colour is a guide.</p><div class="purchase-facts"><div><b>Use</b><span>Apply a small amount to lips with the applicator.</span></div><div><b>Ingredients</b><span>Castor oil, beeswax, jojoba oil, vitamin E and pigments. {a('05-product-facts','Read full list')}</span></div></div><div class="buy-row"><label class="quantity"><button aria-label="Decrease quantity">−</button><output>1</output><button aria-label="Increase quantity">+</button></label><button class="button add-bag" id="add-bag">Add to bag — ₹520</button></div><p class="availability" id="stock-state">{ic('Check')} Available in Rosewater</p><p class="small live-message" role="status"></p><div class="purchase-links">{a('05-product-facts','Ingredients & directions '+ic('ArrowRight'))}{a('06-product-continuation','The rest of your routine '+ic('ArrowRight'))}</div></div></div></main>'''
