def profile():return account('Your everyday space.','Manage your details and revisit your Dewdrop orders.',f'''<section class="welcome-panel"><div>{eyebrow('WELCOME BACK, ASHA')}<h2>Good to see you.</h2><p>Your LetBuyy buyer account is shared.<br>These orders belong to Dewdrop.</p></div>{ic('UserRound')}</section><div class="dashboard-cards"><a href="13-orders.html"><span>Orders</span><strong>1</strong><p>View your Dewdrop purchase {ic('ArrowRight')}</p></a><a href="15-addresses.html"><span>Saved addresses</span><strong>2</strong><p>Manage your delivery details {ic('ArrowRight')}</p></a></div><section class="panel"><div class="section-heading"><h2>Profile details</h2><button class="text-button">Edit details</button></div><div class="form-grid">{field('Full name','Asha Rao')}<div class=field><label for=profile-email>Email address</label><input id=profile-email type=email value=asha@example.test readonly aria-readonly=true><small>Sign-in email</small></div></div><div class="form-actions">{btn('Save changes')}<span class="small">Updates are not saved in this design preview.</span></div></section><section class="panel"><h2>Latest order</h2><div class="order-card-row"><div><strong>DD-1042</strong><p>18 October 2026 · 2 items · ₹1,220</p></div><span class="status">Processing · Mock</span>{a('14-order-detail','View order '+ic('ArrowRight'),'text-link')}</div></section>''')
def orders():return account('Your orders.','Dewdrop purchases for this signed-in buyer.',f'''<section class="panel"><div class="section-heading"><div><h2>Order DD-1042</h2><p>18 October 2026</p></div><span class="status">Processing · Mock</span></div><div class="order-product-row">{im('tint','Soft Colour Rosewater')}{im('cleanser','Cloud Rinse')}<div><h3>Soft Colour & Cloud Rinse</h3><p>Rosewater · RW01 / 150 ml</p><p>2 items · ₹1,220 · Tax included</p></div></div><div class="order-card-row"><span class="mode-badge">MOCK ORDER · No fulfillment</span>{a('14-order-detail','View owned order '+ic('ArrowRight'),'button secondary')}</div></section><div class="pagination"><span>Showing 1 of 1 order</span><nav aria-label="Orders pagination"><button disabled>Previous</button><span aria-current="page">1</span><button disabled>Next</button></nav></div><div class="quiet-note">Looking for a purchase from another merchant? View it in the relevant store or your platform account.</div>''','Orders')
def order_detail():return account('Order DD-1042','Placed 18 October 2026 · Owned synthetic order fixture.',f'''<div class="order-card-row"><span class="status">Processing · Mock</span>{a('13-orders','All orders','text-link')}</div><section class="panel"><h2>Order progress</h2><ol class="order-progress"><li class="done">Order recorded</li><li class="current">Processing</li><li>Shipment not created</li></ol><p class="small">Mock order. No carrier tracking or delivery date is available.</p></section><section class="panel"><h2>What you chose</h2><div class="summary-item">{im('tint','Soft Colour Rosewater lip tint')}<div><strong>Soft Colour lip tint</strong><p>Rosewater · RW01 · 6 ml · Qty 1</p></div><b>₹520</b></div><div class="summary-item">{im('cleanser','Cloud Rinse cleanser')}<div><strong>Cloud Rinse</strong><p>150 ml · Default variant · Qty 1</p></div><b>₹640</b></div><dl class="totals"><div><dt>Subtotal</dt><dd>₹1,160</dd></div><div><dt>Shipping</dt><dd>₹60</dd></div><div><dt>Tax</dt><dd>Included in prices</dd></div><div class="total"><dt>Total</dt><dd>₹1,220</dd></div></dl></section><div class="two-panel"><section class="panel"><h2>Delivery address</h2><p>Asha Rao<br>12 Sample Lane, Design Quarter<br>Bengaluru, Karnataka 560001<br>India</p></section><section class="panel"><h2>Payment & help</h2><p>Mock payment recorded · ₹1,220</p><p class="small">This is not proof of a real payment.</p><button class="text-button">Ask about this order</button><p class="small">Quote DD-1042 when you contact Dewdrop.</p></section></div>''','Orders')
def addresses():return account('Saved addresses.','Choose a default or update your delivery details.',f'''<div class="address-cards"><section class="panel address-card"><div class="section-heading"><h2>Home</h2><span class="status">Default</span></div><p>Asha Rao<br>12 Sample Lane, Design Quarter<br>Bengaluru, Karnataka 560001<br>India</p><div class="form-actions"><button class="text-button">Edit</button><button class="text-button">Remove</button></div></section><section class="panel address-card"><h2>Studio</h2><p>Asha Rao<br>8 Example Road<br>Bengaluru, Karnataka 560002<br>India</p><div class="form-actions"><button class="text-button">Edit</button><button class="text-button">Set as default</button></div></section></div><section class="panel address-editor"><div class="section-heading"><div>{eyebrow('EDITING HOME')}<h2>Update address</h2></div><span class="small">Unsaved changes</span></div><div class="form-grid">{field('Full name *','Asha Rao',True)}{field('Address line 1 *','12 Sample Lane',True)}{field('Address line 2','Design Quarter',True)}{field('City *','Bengaluru')}{field('State *','Karnataka')}{field('PIN code *','5600',error='Enter a 6-digit Indian PIN code.')}{field('Country','India')}</div><label class="check-line"><input type="checkbox" checked>Use as my default address</label><div class="form-actions">{btn('Save address')}{btn('Cancel',secondary=True)}</div><p class="small">Correct the PIN code before saving. Other details remain entered.</p></section>''','Addresses')
scenes=[('01-home-top','Home · opening','Routine-led hero, explicit shop entry and step navigation.',home_top),('02-home-bottom','Home · continuation','Independent products, factual education, service links and footer.',home_bottom),('03-collection','Shop by use','Routine shelves, typed facet proposal, sorting and pagination.',collection),('04-product-selection','PDP · shade selection','Gallery, actual named variants, ingredient/use summary and buy action.',selection),('05-product-facts','PDP · ingredients & use','Full ingredients, directions and honest missing facts.',facts),('06-product-continuation','PDP · your routine','Independent related items and truthful policy availability.',continuation),('07-cart','Your bag','Named variants, quantity/remove, arithmetic and recoverable update.',cart),('08-checkout-address','Checkout · address','Canonical contact/address/shipping and server quote fixture.',address),('09-checkout-review','Checkout · review & pay','Full summary, eligible-method proposal and payment-start retry.',review),('10-sign-in','LetBuyy · sign in','Canonical shared identity with explicit Dewdrop destination.',lambda:identity(False)),('11-create-account','LetBuyy · create account','Email/password creation followed by explicit signed-in Continue to Dewdrop state.',lambda:identity(True)),('12-profile','Profile overview','Store account, supported editing and navigation.',profile),('13-orders','Order history','Owned store orders with mock status and pagination.',orders),('14-order-detail','Owned order detail','Exact selected variants, totals, status and support boundary.',order_detail),('15-addresses','Saved addresses','Two address states plus edit validation/default.',addresses)]
for id,title,desc,fun in scenes:
 (S/(id+'.html')).write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dewdrop · {title}</title><link rel="stylesheet" href="styles.css"><script defer src="interactions.js"></script></head><body><a class="skip-link" href="#main-content">Skip to content</a><div id="main-content">{fun()}</div></body></html>')
(R/'scenes.json').write_text(json.dumps([dict(id=id,title=t,description=d,source='source/'+id+'.html') for id,t,d,f in scenes],indent=2))
(R/'fixtures.json').write_text(json.dumps({'fictional':True,'domain':'dewdrop.example.test','buyer':{'name':'Asha Rao','email':'asha@example.test'},'catalog':P,'variants':[{'id':'tint-rosewater','name':'Rosewater','code':'RW01','color':'#a36a65','available':True},{'id':'tint-pink-clay','name':'Pink Clay','code':'PC02','color':'#a36a65','available':True},{'id':'tint-terracotta','name':'Terracotta','code':'TC03','color':'#9a5944','available':False}],'cart':{'lines':[{'product':'soft-colour','variant':'tint-rosewater','quantity':1,'unitMinor':52000},{'product':'cloud-rinse','variant':'default','quantity':1,'unitMinor':64000}],'subtotalMinor':116000,'shippingMinor':6000,'totalMinor':122000,'tax':'included'},'order':{'id':'DD-1042','date':'2026-10-18','mode':'mock','state':'processing','totalMinor':122000}},indent=2))
print('Built',len(scenes),'source scenes')
